#!/usr/bin/env bash
# Active le React Compiler : option reactCompiler dans next.config.ts, paquet babel-plugin-react-compiler
# (installé par ce script avec pnpm add), et chapitre « Typecheck et lint » mis à jour.
# Prérequis : apply-docs-configuration-1.sh.
# Usage (racine du repo) : bash apply-react-compiler.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/next.config.ts" 2>/dev/null | grep -qF "reactCompiler: true"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "Partie suivante : la configuration" "apps/web/content/docs/dev/demarrer/facon-de-travailler.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-docs-configuration-1.sh"; exit 1; }
MODIFIED=("apps/web/next.config.ts" "apps/web/content/docs/dev/qualite/typecheck-et-lint.mdx" "apps/web/content/docs/dev/configuration/typescript-et-tsconfig.mdx")
CREATED=()
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "reactCompiler: true" "apps/web/next.config.ts" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
trap 'restore' ERR


python3 - <<'PY'
import base64
spec_skip_done = False
def sub(path, old, new):
    old, new = base64.b64decode(old).decode(), base64.b64decode(new).decode()
    s = open(path, encoding="utf-8").read()
    if s.count(old) == 0 and s.count(new) == 1 and spec_skip_done: return  # déjà fait par un script précédent
    assert s.count(old) == 1, (path, old[:80], s.count(old))
    open(path, "w", encoding="utf-8").write(s.replace(old, new))
sub('apps/web/next.config.ts', 'ICAgKi8KICBvdXRwdXQ6ICJzdGFuZGFsb25lIiwKCiAgLyoqCg==',
    '')
sub('apps/web/content/docs/dev/qualite/typecheck-et-lint.mdx', '',
    '')
sub('apps/web/content/docs/dev/qualite/typecheck-et-lint.mdx', '',
    '')
sub('apps/web/content/docs/dev/qualite/typecheck-et-lint.mdx', '',
    '')
sub('apps/web/content/docs/dev/qualite/typecheck-et-lint.mdx', '',
    '')
sub('apps/web/content/docs/dev/configuration/typescript-et-tsconfig.mdx', 'CjxDYWxsb3V0IHR5cGU9InRpcCI+CioqQ2hhcGl0cmUgc3VpdmFudCA6IE5leHQuanMgZXQgbmV4dC5jb25maWcudHMuKiogTGUgYnVpbGQgYXV0b25vbWUgcG91ciBsJ2ltYWdlIERvY2tlciwgbGVzIHJlZGlyZWN0aW9ucywgTURYLCBldCBjZSBxdWUgY2hhcXVlIHLDqWdsYWdlIGNoYW5nZS4KPC9DYWxsb3V0Pgo=',
    'CjxDYWxsb3V0IHR5cGU9InRpcCI+CioqQ2hhcGl0cmUgc3VpdmFudCA6IE5leHQuanMgZXQgbmV4dC5jb25maWcudHMuKiogTGUgYnVpbGQgYXV0b25vbWUgcG91ciBsJ2ltYWdlIERvY2tlciwgbGUgUmVhY3QgQ29tcGlsZXIsIGxlcyByZWRpcmVjdGlvbnMsIE1EWCwgZXQgY2UgcXVlIGNoYXF1ZSByw6lnbGFnZSBjaGFuZ2UuCjwvQ2FsbG91dD4K')
print("  édits ok (6 substitutions, 0 fichiers créés, 0 remplacés)")
PY
trap - ERR

[ "${AKFC_APPLY_ONLY:-0}" = "1" ] && { echo "Appliqué (sans vérification ni commit)."; exit 0; }
echo "== installation de babel-plugin-react-compiler =="
if ! pnpm add -D babel-plugin-react-compiler@1.0.0 --filter web > /tmp/akfc_add.log 2>&1; then
  echo "❌ installation ÉCHOUÉE :"; grep -v '^[[:space:]]*$' /tmp/akfc_add.log | tail -8
  git checkout -q -- apps/web/package.json pnpm-lock.yaml; restore; exit 1
fi
grep -q '"babel-plugin-react-compiler"' apps/web/package.json || { echo "❌ paquet absent de apps/web/package.json"; git checkout -q -- apps/web/package.json pnpm-lock.yaml; restore; exit 1; }
echo "  ✅ paquet installé"
echo "== pnpm check =="
if pgrep -f "next dev" >/dev/null 2>&1; then
  echo "  (pnpm dev tourne : vérification sans effacer .next)"
  CHECK="node scripts/check-next-conventions.mjs && node scripts/check-tour-targets.mjs && pnpm --filter backend typecheck && pnpm typecheck && pnpm lint"
else
  CHECK="pnpm check"
fi
if ! bash -c "$CHECK" > /tmp/akfc_tc.log 2>&1; then
  echo "❌ check ÉCHOUÉ :"
  grep -nE "error TS|✗ tutos|ERR_|Error:|EACCES|Permission denied" /tmp/akfc_tc.log | head -12
  echo "  … fin du journal :"; grep -v '^[[:space:]]*$' /tmp/akfc_tc.log | tail -15
  git checkout -q -- apps/web/package.json pnpm-lock.yaml; pnpm install >/dev/null 2>&1 || true; restore; exit 1
fi
echo "  ✅ check OK"
git add "${MODIFIED[@]}" "${CREATED[@]}" apps/web/package.json pnpm-lock.yaml
git commit -F - >/tmp/c.log 2>&1 <<'MSG' && echo "✅ commit $(git rev-parse --short HEAD)" || { echo "commit KO"; tail -3 /tmp/c.log; }
